"""Migrated ORD_HEADER discount validation rules."""

from decimal import Decimal, InvalidOperation


class BusinessRuleViolation(Exception):
    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


def _is_in_discount_range(pct: object) -> bool:
    """Return whether pct is numerically within the inclusive legacy range."""
    try:
        value = Decimal(str(pct))
        return Decimal("0") <= value <= Decimal("100")
    except (InvalidOperation, TypeError, ValueError):
        return False


def _lookup_role(user_id: str, users: list[dict]) -> str:
    """Apply legacy LOOKUP semantics for USR_MASTER ROLE_ID."""
    for user in users:
        if user.get("USR_ID") == user_id and user.get("DEL_FLG", "") != "Y":
            return user.get("ROLE_ID", "")
    return ""


def set_discount(order: dict, pct, user_id: str, users: list[dict]) -> dict:
    """Validate and set an order discount according to ORD-001 and ORD-002."""
    if not _is_in_discount_range(pct):
        raise BusinessRuleViolation("E5001", "Discount out of range")

    try:
        over_twenty = Decimal(str(pct)) > Decimal("20")
    except (InvalidOperation, TypeError, ValueError):
        # Invalid numeric values have already been rejected by ORD-001.
        over_twenty = False

    if over_twenty:
        role = _lookup_role(user_id, users)
        if role not in ("MGR", "ADMIN"):
            raise BusinessRuleViolation(
                "E5002",
                "Discount over 20 percent requires manager role",
            )

    updated_order = dict(order)
    updated_order["DISC_PCT"] = pct
    return updated_order
